  1 // Serializes one frame's DOM into compact text for the model, with refs for interactive elements.
  2 // Rules (docs/05-browser-playbook.md): drop aria-hidden decoys and closed dialogs; keep tooltips (via
  3 // aria-describedby, title, aria-description), collapsed <details> content, canvas/role=img labels, ::before
  4 // data-labels, <time datetime>;
  5 // restore logical order (aria-posinset / CSS order); strip zero-width characters.
  6 (opts) => {
  7   const prefix = opts.prefix || "e";
  8   const ZW = /[​-‍⁠﻿­]/g;
  9   const clean = (s) => (s || "").replace(ZW, "").replace(/ /g, " ").replace(/\s+/g, " ").trim();
 10   const SKIP = new Set(["SCRIPT", "STYLE", "NOSCRIPT", "TEMPLATE", "HEAD", "META", "LINK"]);
 11   const BLOCK = new Set(["P", "DIV", "SECTION", "ARTICLE", "MAIN", "ASIDE", "HEADER", "FOOTER", "NAV", "UL", "OL",
 12     "LI", "DL", "DT", "DD", "FORM", "FIELDSET", "LEGEND", "TABLE", "THEAD", "TBODY", "TFOOT", "TR", "H1", "H2", "H3",
 13     "H4", "H5", "H6", "PRE", "BLOCKQUOTE", "DETAILS", "SUMMARY", "DIALOG", "CAPTION", "FIGURE", "BR", "HR", "LABEL"]);
 14   let n = 0;
 15   document.querySelectorAll("[data-agent-ref]").forEach((e) => e.removeAttribute("data-agent-ref"));
 16 
 17   const byId = (id) => (id ? document.getElementById(id) : null);
 18   const describedTexts = (el) => {
 19     const ids = (el.getAttribute("aria-describedby") || "").split(/\s+/).filter(Boolean);
 20     const texts = ids.map((id) => clean(byId(id)?.textContent)).filter(Boolean);
 21     // Native hover texts (title, aria-description) are what a person sees too; skip mere repeats of the own text.
 22     const own = clean(el.textContent);
 23     for (const extra of [el.getAttribute("aria-description"), el.getAttribute("title")]) {
 24       const s = clean(extra);
 25       if (s && s !== own && !texts.includes(s)) texts.push(s);
 26     }
 27     return texts;
 28   };
 29   const referencedTooltip = new Set();
 30   document.querySelectorAll("[aria-describedby]").forEach((el) =>
 31     (el.getAttribute("aria-describedby") || "").split(/\s+/).forEach((id) => id && referencedTooltip.add(id)));
 32 
 33   const styleOf = (el) => { try { return getComputedStyle(el); } catch { return null; } };
 34   const cssHidden = (el) => {
 35     if (el.hidden) return true;
 36     const cs = styleOf(el);
 37     return !!cs && (cs.display === "none" || cs.visibility === "hidden");
 38   };
 39   const isInteractive = (el) => {
 40     const t = el.tagName;
 41     if (t === "A") return el.hasAttribute("href");
 42     if (["BUTTON", "SELECT", "TEXTAREA"].includes(t)) return true;
 43     if (t === "INPUT") return el.type !== "hidden";
 44     if (t === "SUMMARY") return true;
 45     const role = el.getAttribute("role");
 46     return ["button", "link", "menuitem", "tab", "checkbox", "radio", "option", "switch"].includes(role);
 47   };
 48   const ref = (el) => { const r = prefix + (++n); el.setAttribute("data-agent-ref", r); return r; };
 49 
 50   // Accessible name of a control.
 51   const labelText = (el) => {
 52     const parts = [];
 53     const walk = (node) => {
 54       if (node.nodeType === 3) { parts.push(node.textContent); return; }
 55       if (node.nodeType !== 1 || SKIP.has(node.tagName)) return;
 56       if (node.getAttribute("aria-hidden") === "true") return;
 57       if (node !== el && ["INPUT", "SELECT", "TEXTAREA", "BUTTON"].includes(node.tagName)) return;
 58       if (node.getAttribute("data-label")) { parts.push(node.getAttribute("data-label")); return; }
 59       if (node.getAttribute("role") === "img" && node.getAttribute("aria-label")) { parts.push(node.getAttribute("aria-label")); return; }
 60       node.childNodes.forEach(walk);
 61     };
 62     walk(el);
 63     return clean(parts.join(" "));
 64   };
 65   const nameOf = (el) => {
 66     const aria = el.getAttribute("aria-label");
 67     if (aria) return clean(aria);
 68     const lb = el.getAttribute("aria-labelledby");
 69     if (lb) return clean(lb.split(/\s+/).map((id) => byId(id)?.textContent || "").join(" "));
 70     if (el.labels && el.labels.length) return labelText(el.labels[0]);
 71     if (["INPUT", "TEXTAREA", "SELECT"].includes(el.tagName)) return clean(el.placeholder || el.name || el.title || "");
 72     return clean(labelText(el) || el.title || el.value || "");
 73   };
 74 
 75   const controlLine = (el, hiddenCtx) => {
 76     const t = el.tagName;
 77     const r = ref(el);
 78     const flags = [];
 79     if (el.disabled || el.closest("[inert]") || el.closest("fieldset[disabled]")) flags.push("disabled");
 80     if (hiddenCtx) flags.push("hidden-until-hover/open");
 81     const info = describedTexts(el).filter((s) => s !== nameOf(el));   // a title used as the name is not extra info
 82     let s;
 83     if (t === "A") {
 84       const href = el.getAttribute("href");
 85       s = `[${r}] link "${nameOf(el)}" -> ${href}` + (el.target ? ` (target=${el.target})` : "");
 86     } else if (t === "SELECT") {
 87       const opts = [...el.options].map((o) => (o.selected ? `*${clean(o.textContent)}*` : clean(o.textContent)) + (o.value !== clean(o.textContent) ? `{${o.value}}` : ""));
 88       s = `[${r}] select "${nameOf(el)}" options: ${opts.join(" | ")}`;
 89     } else if (t === "TEXTAREA") {
 90       s = `[${r}] textarea "${nameOf(el)}" value="${clean(el.value)}"`;
 91     } else if (t === "INPUT") {
 92       const ty = el.type;
 93       if (ty === "checkbox" || ty === "radio") s = `[${r}] ${ty} "${nameOf(el)}" ${el.checked ? "[x]" : "[ ]"}`;
 94       else if (ty === "range") s = `[${r}] slider "${nameOf(el)}" value=${el.value} min=${el.min || 0} max=${el.max || 100}`;
 95       else if (ty === "submit" || ty === "button") s = `[${r}] button "${clean(el.value) || nameOf(el)}"`;
 96       else s = `[${r}] input[${ty}] "${nameOf(el)}" value="${clean(el.value)}"`;
 97     } else if (t === "SUMMARY") {
 98       const d = el.parentElement;
 99       s = `[${r}] summary "${labelText(el)}" (${d && d.open ? "open" : "collapsed; content shown below"})`;
100     } else {
101       const role = el.getAttribute("role") || t.toLowerCase();
102       s = `[${r}] ${role === "button" || t === "BUTTON" ? "button" : role} "${nameOf(el)}"`;
103       if (el.getAttribute("aria-expanded")) s += ` expanded=${el.getAttribute("aria-expanded")}`;
104     }
105     if (flags.length) s += ` (${flags.join(", ")})`;
106     if (info.length) s += ` [info: ${info.join(" / ")}]`;
107     return s;
108   };
109 
110   const out = [];
111   let line = [];
112   const flush = () => { const s = clean(line.join(" ")); if (s) out.push(s); line = []; };
113   const emit = (s) => { if (s) line.push(s); };
114 
115   const orderedChildren = (el) => {
116     const kids = [...el.childNodes];
117     const keyed = kids.map((k, i) => {
118       if (k.nodeType !== 1) return { k, i, key: 0 };
119       const pos = k.getAttribute("aria-posinset");
120       const ord = parseInt(styleOf(k)?.order || "0", 10) || 0;
121       return { k, i, key: pos ? parseInt(pos, 10) : ord };
122     });
123     if (keyed.some((x) => x.key !== 0)) keyed.sort((a, b) => a.key - b.key || a.i - b.i);
124     return keyed.map((x) => x.k);
125   };
126 
127   const walk = (node, hiddenCtx) => {
128     if (node.nodeType === 3) { if (!hiddenCtx) emit(node.textContent.replace(ZW, "")); return; }
129     if (node.nodeType !== 1) return;
130     const el = node;
131     const t = el.tagName;
132     if (SKIP.has(t)) return;
133     if (el.getAttribute("aria-hidden") === "true") return;               // decoys and decoration
134     if (t === "DIALOG" && !el.open) return;                               // closed popups
135     const role = el.getAttribute("role");
136     if (role === "tooltip" && el.id && referencedTooltip.has(el.id)) return; // shown as [info: …] on its trigger
137     // Content of collapsed <details> is not rendered but computes as visible, so it is kept as real content. An
138     // element hidden explicitly (hidden, display:none, visibility:hidden) stays hidden there too: that is where decoys sit.
139     const effHidden = hiddenCtx || cssHidden(el);
140     const block = BLOCK.has(t);
141     if (block) flush();
142     if (t === "IFRAME" || t === "FRAME") {
143       emit(`[iframe "${clean(el.title || el.name)}" src=${el.getAttribute("src") || ""}${el.hasAttribute("srcdoc") ? " (srcdoc)" : ""}] (content listed as its own frame)`);
144       flush(); return;
145     }
146     if (/^H[1-6]$/.test(t) && !effHidden) emit("#".repeat(+t[1]));
147     if (t === "DIALOG" || role === "dialog" || role === "alertdialog") {
148       emit(`[DIALOG OPEN "${nameOf(el)}"]`); flush();
149     }
150     if (isInteractive(el)) {
151       if (!effHidden || t === "A" || t === "BUTTON") { flush(); out.push(controlLine(el, effHidden)); }
152       return;  // the control line carries its name; no need to walk inside
153     }
154     if (t === "LABEL" && el.querySelector("input,select,textarea") && !effHidden) {
155       el.querySelectorAll("input,select,textarea").forEach((c) => { if (c.type !== "hidden") { flush(); out.push(controlLine(c, false)); } });
156       flush(); return;  // the label text is already the controls' name
157     }
158     if (effHidden) {
159       // Hidden subtree: only surface controls (menus that open on hover), never hidden text.
160       el.querySelectorAll("a[href],button").forEach((c) => {
161         if (c.closest("[aria-hidden='true']") || c.closest("dialog:not([open])")) return;
162         flush(); out.push(controlLine(c, true));
163       });
164       return;
165     }
166     if (t === "CANVAS" || t === "IMG" || t === "SVG" || role === "img") {
167       const label = clean(el.getAttribute("aria-label") || el.getAttribute("alt") || el.getAttribute("title") || (t === "CANVAS" ? el.textContent : ""));
168       emit(label ? `[${t === "IMG" || t === "CANVAS" ? t.toLowerCase() : "img"}: ${label}]` : (t === "IMG" ? "[image without text]" : ""));
169       if (t === "CANVAS" && !label) emit("[canvas without text: needs screenshot]");
170       if (block) flush();
171       return;
172     }
173     if (el.getAttribute("data-label") && !el.textContent.trim()) emit(el.getAttribute("data-label"));
174     if (t === "TIME" && el.getAttribute("datetime")) { emit(`${clean(el.textContent)} (${el.getAttribute("datetime")})`); return; }
175     if (role === "tooltip") { emit(`[tooltip: ${clean(el.textContent)}]`); return; }
176     if (t === "TR") {
177       const cells = [...el.children].filter((c) => c.tagName === "TD" || c.tagName === "TH");
178       const saved = out.length;
179       const texts = cells.map((c) => {
180         const before = out.length; line = [];
181         orderedChildren(c).forEach((k) => walk(k, false));
182         flush();
183         const parts = out.splice(before);
184         return parts.join(" ; ");
185       });
186       out.length = saved;
187       out.push("| " + texts.join(" | ") + " |");
188       return;
189     }
190     const extra = describedTexts(el);
191     orderedChildren(el).forEach((k) => walk(k, false));
192     if (extra.length) emit(`[info: ${extra.join(" / ")}]`);
193     if (block) flush();
194   };
195 
196   walk(document.body || document.documentElement, false);
197   flush();
198   const tz = (document.body?.innerText.match(/Zeit(?:zone|angaben)\s*:\s*([A-Za-z_\/]+|UTC)/) || [])[1];
199   return { text: out.join("\n"), refs: n, title: document.title, timezone: tz || null };
200 }
  1 // Generic page guards (no site-specific selectors). op: state | consent | close_overlays | unlock_gates
  2 (args) => {
  3   const op = args.op;
  4   const txt = (e) => (e?.innerText || e?.textContent || "").replace(/[​-‍⁠﻿]/g, "").trim();
  5   const name = (e) => ((e.getAttribute("aria-label") || "") + " " + txt(e) + " " + (e.value || "")).toLowerCase();
  6   const visible = (e) => { const r = e.getBoundingClientRect(); const cs = getComputedStyle(e);
  7     return r.width > 0 && r.height > 0 && cs.visibility !== "hidden" && cs.display !== "none"; };
  8   const body = txt(document.body).slice(0, 4000);
  9   const clickables = (root) => [...root.querySelectorAll("button, a[href], input[type=submit], input[type=button], [role=button]")];
 10   const BAD = /akzeptieren und fortfahren|umfrage|bewert|feedback|survey|rate us|teilnehmen|zur befragung/;
 11 
 12   if (op === "state") {
 13     const hasPassword = [...document.querySelectorAll("input[type=password]")].some(visible);
 14     const errorPage = document.querySelectorAll("a,button,input,select").length < 25 &&
 15       /vorübergehend nicht verfügbar|service unavailable|bad gateway|gateway timeout|interner fehler|internal server error|fehler 50\d|error 50\d/i.test(body);
 16     let retry = null;
 17     if (errorPage) {
 18       const a = [...document.querySelectorAll("a[href]")].find((x) => /erneut|nochmal|retry|wiederholen/i.test(txt(x)));
 19       retry = a ? a.getAttribute("href") : null;
 20     }
 21     const consent = !hasPassword && /cookie/i.test(body) &&
 22       clickables(document).some((b) => visible(b) && /cookie|akzeptier|zustimm|einverstanden|accept/.test(name(b)));
 23     const pending = [...document.querySelectorAll("dialog:not([open])")].length > 0;
 24     return { login: hasPassword, error_page: errorPage, retry_href: retry, consent, pending_dialogs: pending };
 25   }
 26 
 27   if (op === "consent") {
 28     const buttons = clickables(document).filter(visible);
 29     const pick = buttons.find((b) => /notwendig|necessary|essential|erforderlich/.test(name(b)) && /akzept|accept|nur|only|zulassen|allow/.test(name(b)))
 30       || buttons.find((b) => /notwendig|necessary/.test(name(b)))
 31       || buttons.find((b) => /akzeptier|accept|zustimm|einverstanden/.test(name(b)) && !BAD.test(name(b)));
 32     if (pick) { pick.click(); return true; }
 33     return false;
 34   }
 35 
 36   if (op === "close_overlays") {
 37     let closed = 0;
 38     const overlays = [...document.querySelectorAll("dialog[open], [role=dialog][aria-modal=true], [role=alertdialog]")]
 39       .filter((d) => d.tagName === "DIALOG" || visible(d));
 40     for (const d of overlays) {
 41       const buttons = clickables(d);
 42       const close = buttons.find((b) => /schlie|close|^\s*[×✕x]\s*$|später|nicht jetzt|nein danke|no thanks|abbrechen|ausblenden/.test(name(b).trim()) && !BAD.test(name(b)));
 43       if (close) { close.click(); closed++; continue; }
 44       if (d.tagName === "DIALOG" && typeof d.close === "function") { d.close(); closed++; }
 45     }
 46     return closed;
 47   }
 48 
 49   if (op === "unlock_gates") {
 50     // "drag to unlock" sliders and "I am not a robot" boxes that keep a fieldset disabled/inert.
 51     let done = 0;
 52     for (const r of document.querySelectorAll("input[type=range]")) {
 53       const label = ((r.getAttribute("aria-label") || "") + " " + txt(r.closest("label") || r.parentElement)).toLowerCase();
 54       if (!/entsperr|unlock|zieh|slide|schieb/.test(label)) continue;
 55       const max = r.max || "100";
 56       if (r.value !== max) {
 57         const setter = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, "value").set;
 58         setter.call(r, max);
 59         r.dispatchEvent(new Event("input", { bubbles: true }));
 60         r.dispatchEvent(new Event("change", { bubbles: true }));
 61         done++;
 62       }
 63     }
 64     for (const c of document.querySelectorAll("input[type=checkbox]")) {
 65       const label = txt(c.closest("label") || c.parentElement).toLowerCase();
 66       if (/roboter|robot|kein bot|human|mensch/.test(label) && !c.checked) { c.click(); done++; }
 67     }
 68     return done;
 69   }
 70   return null;
 71 }

