import json, re
def load(name):
    out = []
    for l in open(name):
        if not l.startswith("{"): continue
        try: out.append(json.loads(l, strict=False))
        except Exception:
            m = re.match(r'\{"t": ([\d.]+), "event": "(\w+)"', l)
            if m: out.append({"t": float(m.group(1)), "event": m.group(2), "_trunc": l[:300]})
    return out
ev = load("spec3.log")
for mission in ["specification@customer-portal", "erp:GR-6617@erp", "erp:GR-5152@erp", "mail@mail"]:
    print("=====", mission)
    prev = None
    for e in ev:
        if e.get("mission") == mission and e["event"] == "action":
            t = e["t"]; dt = t - prev if prev else 0; prev = t
            args = json.dumps(e.get("args"), ensure_ascii=False)
            print(f"  {t:6.1f} (+{dt:5.1f}) {e['step']:2} {e['tool']:14} {args[:105]:105} -> {str(e.get('result'))[:70]}")
EOF

