    async def _do_fill_form(self, fields: list, apply: str | None = None, then_click: str | None = None) -> str:
        """A whole form step in one call, addressed by the labels the model reads (refs change after every apply; a ref
        of the current page is accepted too). Fields are set in the given order; a field that is still disabled is
        unlocked by pressing the form's apply button first, and after a choice the apply button is pressed while any
        field of the page is still disabled (cascading filters, also across calls). Finally `then_click` (e.g. next) is
        pressed. Every value is read back."""
        results, applied = [], 0
        for field in fields or []:
            label, value = str(field.get("field") or field.get("label") or field.get("ref") or ""), field.get("value")
            text = await self.observe(limit=200000)
            control, problem = _field_control(text, field)
            if control and control["disabled"] and apply and applied < 2 * len(fields):
                applied += 1
                await self._press(apply)
                text = await self.observe(limit=200000)
                control, problem = _field_control(text, field)
            if not control:
                results.append(f"{label}: ERROR {problem}")
                continue
            if control["disabled"] and not apply:
                buttons = " | ".join(f'"{c}"' for c in _control_names(text, BUTTON_KINDS)[:15])
                results.append(f"{label}: ERROR disabled until an earlier choice is applied: call again with "
                               f"apply=<the form's apply button>. Buttons on this page: {buttons}")
                continue
            ref = control["ref"]
            if control["kind"] == "select":
                outcome = await self._select(ref, str(value))
            elif control["kind"] in ("checkbox", "radio"):
                outcome = await self._do_check(ref, str(value).lower() not in ("false", "0", "no", "nein", ""))
            else:
                outcome = await self._do_type(ref, str(value))
            results.append(f"{label}: {outcome}")
            if apply and control["kind"] == "select" and not outcome.startswith("ERROR") and applied < 2 * len(fields):
                waiting = [c for c in _controls(await self.observe(limit=200000), FIELD_KINDS) if c["disabled"]]
                if waiting:                          # the choice unlocks further fields only once it is applied
                    applied += 1
                    await self._press(apply)
        if then_click and any(": ERROR" in line for line in results):
            results.append(f"then {then_click}: NOT pressed because of the errors above. Fix only the failed fields "
                           "(with fill_form again), then press it.")
        elif then_click:
            results.append(f"then {then_click}: " + await self._press(then_click))
        return "\n".join(results)

    async def _press(self, label: str) -> str:
def _controls(observation: str, kinds: tuple[str, ...]) -> list[dict]:
    found = []
    for line in observation.splitlines():
        match = _CONTROL_LINE.match(line.strip())
        if match and match.group("kind") in kinds:
            flags = _FLAGS.search(match.group("rest"))
            found.append({"ref": match.group("ref"), "kind": match.group("kind"), "name": match.group("name"),
                          "disabled": bool(flags and flags.group(1) == "disabled")})
    return found


def _field_control(observation: str, field: dict) -> tuple[dict | None, str]:
    """The control a fill_form field means: by its label, or by a ref of the current page."""
    ref = str(field.get("ref") or "").strip("[]\"' ")
    if ref and not (field.get("field") or field.get("label")):
        hit = next((c for c in _controls(observation, FIELD_KINDS) if c["ref"] == ref), None)
        return (hit, "") if hit else (None, f"no form field with ref {ref} on the current page")
    return _find_control(observation, str(field.get("field") or field.get("label") or ""), FIELD_KINDS)


def _control_names(observation: str, kinds: tuple[str, ...]) -> list[str]:
    return list(dict.fromkeys(c["name"] for c in _controls(observation, kinds)))


