"""fill_form: a whole form step with cascading filters in one call (synthetic page, no network, no model).

The page re-renders its form after every apply, as such configurators do: refs of an earlier observation are gone,
so the tool must find each field again by its label."""
import asyncio
import re
from urllib.parse import parse_qs, urlparse

from playwright.async_api import async_playwright

from rfq.browser.site import Site

BASE = "http://config.test"
FORM = """<html><body><h1>Position 7</h1><form id="f" action="/next" method="get"></form>
<script>
const opts = {d: ["10", "20", "30"], l: {"10": ["100", "200"], "20": ["150", "250"], "30": ["300"]},
              a: {"150": ["Stift", "Kugel"], "250": ["Stift"]}};
let state = {step: 0, d: "", l: "", a: ""};
function sel(name, label, values, value, enabled) {
  const o = ['<option value="">Bitte wählen</option>'].concat(values.map(v => `<option${v === value ? " selected" : ""}>${v}</option>`));
  return `<label>${label} <select name="${name}"${enabled ? "" : " disabled"}>${o.join("")}</select></label><br>`;
}
function render() {
  const f = document.getElementById("f");
  const articles = state.step >= 3 ? ["X-" + state.d + state.l + state.a, "Y-1"] : [];
  f.innerHTML = sel("d", "Durchmesser", opts.d, state.d, true)
    + sel("l", "Länge", state.step >= 1 ? opts.l[state.d] || [] : [], state.l, state.step >= 1)
    + sel("a", "Ausführung", state.step >= 2 ? opts.a[state.l] || [] : [], state.a, state.step >= 2)
    + '<button type="button" id="apply">Auswahl anwenden</button><br>'
    + sel("art", "Artikel", articles, "", state.step >= 3)
    + '<label>Anzahl <input name="qty"></label><br>'
    + '<label><input type="checkbox" name="ok"> Bedingungen gelesen</label><br>'
    + '<button type="submit">Weiter</button>';
  document.getElementById("apply").onclick = () => {
    const v = n => f.querySelector(`[name=${n}]`).value;
    state.d = v("d"); state.l = state.step >= 1 ? v("l") : ""; state.a = state.step >= 2 ? v("a") : "";
    state.step = state.a ? 3 : state.l ? 2 : state.d ? 1 : 0;
    setTimeout(render, 150);
  };
}
render();
</script></body></html>"""


async def _site(p, submitted: list):
    browser = await p.chromium.launch()
    context = await browser.new_context()

    async def handle(route):
        url = urlparse(route.request.url)
        if url.path == "/next":
            submitted.append({k: v[0] for k, v in parse_qs(url.query).items()})
            body = "<html><body><h1>Gespeichert</h1></body></html>"
        else:
            body = FORM
        await route.fulfill(status=200, content_type="text/html; charset=utf-8", body=body)

    await context.route(f"{BASE}/**", handle)
    site = Site("config", BASE, {"username": "u", "password": "p"}, context)
    await site.start()
    return browser, site


def _run(fields, apply="Auswahl anwenden", then_click="Weiter", by_ref=False):
    submitted = []

    async def scenario():
        async with async_playwright() as p:
            browser, site = await _site(p, submitted)
            observation = await site.observe()
            if by_ref:      # the model addresses fields by the refs of the observation it saw before the call
                for field in fields:
                    field["ref"] = re.search(r"\[(\w+)\] \w+(?:\[\w+\])? \"" + field.pop("field"), observation).group(1)
            result = await site.act("fill_form", {"fields": fields, "apply": apply, "then_click": then_click})
            await browser.close()
            return result
    return asyncio.run(scenario()), submitted


CASCADE = [{"field": "Durchmesser", "value": "20"}, {"field": "Länge", "value": "150"},
           {"field": "Ausführung", "value": "Kugel"}, {"field": "Artikel", "value": "X-20150Kugel"},
           {"field": "Anzahl", "value": "7"}, {"field": "Bedingungen gelesen", "value": "true"}]


def test_cascade_and_fields_in_one_call():
    result, submitted = _run([dict(f) for f in CASCADE])
    assert "ERROR" not in result, result
    assert submitted == [{"d": "20", "l": "150", "a": "Kugel", "art": "X-20150Kugel", "qty": "7", "ok": "on"}]


def test_refs_of_the_observation_before_the_call_still_work_after_rerenders():
    fields = [dict(f) for f in CASCADE if f["field"] in ("Durchmesser", "Anzahl")]
    result, submitted = _run(fields, by_ref=True)
    assert "ERROR" not in result, result
    assert submitted and submitted[0]["d"] == "20" and submitted[0]["qty"] == "7"


def test_a_failed_field_stops_before_next():
    fields = [dict(f) for f in CASCADE]
    fields[1]["value"] = "999"
    result, submitted = _run(fields)
    assert "ERROR" in result and "NOT pressed" in result and submitted == []

